import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class GameLoadException extends BaseException {
    constructor(reason: string) {
        super('Game.LoadError', reason);
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
